    }
    .arc-w .sec:first-child { margin-top: 0; }

    .arc-w .it {
        display: flex; align-items: center; gap: 6px;
        padding: 3px 5px; margin-bottom: 3px;
        border: 1px solid hsl(var(--border, 0 22% 17%));
