        background: rgba(0,0,0,0.22);
    }
    .arc-w .lv {
        font-size: 9px; min-width: 22px; text-align: right; flex-shrink: 0;
        color: #86c48f; font-variant-numeric: tabular-nums;
    }
    .arc-w .nm {
        font-size: 11px; flex: 1; min-width: 0;
        overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
        cursor: pointer;
    }
